CREATE TABLE dog (id INT GENERATED BY DEFAULT AS IDENTITY NOT NULL, name VARCHAR(255) NOT NULL, gender VARCHAR(255) DEFAULT NULL, birth_date TIMESTAMP(0) WITHOUT TIME ZONE NOT NULL, adopt_date TIMESTAMP(0) WITHOUT TIME ZONE DEFAULT NULL, weight INT DEFAULT NULL, height INT DEFAULT NULL, status VARCHAR(100) DEFAULT NULL, PRIMARY KEY (id));
CREATE TABLE treatment (id INT GENERATED BY DEFAULT AS IDENTITY NOT NULL, type TEXT NOT NULL, product_name VARCHAR(255) NOT NULL, treatment_date DATE NOT NULL, due_date DATE DEFAULT NULL, note VARCHAR(255) DEFAULT NULL, dog_id INT NOT NULL, PRIMARY KEY (id));
CREATE TABLE dog_media (id INT GENERATED BY DEFAULT AS IDENTITY NOT NULL, dog_id INT NOT NULL, media_type VARCHAR(255) NOT NULL, storage_key VARCHAR(255) NOT NULL, original_name VARCHAR(255) NOT NULL, mime_type VARCHAR(100) NOT NULL, size_bytes BIGINT NOT NULL, width INT DEFAULT NULL, height INT DEFAULT NULL, is_thumbnail BOOLEAN DEFAULT FALSE NOT NULL, is_profile BOOLEAN DEFAULT FALSE NOT NULL, created_at TIMESTAMP(0) WITH TIME ZONE NOT NULL, PRIMARY KEY (id), CONSTRAINT CHK_DOG_MEDIA_TYPE CHECK (media_type IN ('image', 'video')), CONSTRAINT CHK_DOG_MEDIA_THUMBNAIL_TYPE CHECK (is_thumbnail = FALSE OR media_type = 'image'), CONSTRAINT CHK_DOG_MEDIA_TEXT_METADATA CHECK (btrim(storage_key) <> '' AND btrim(original_name) <> '' AND btrim(mime_type) <> '' AND ((media_type = 'image' AND mime_type LIKE 'image/%') OR (media_type = 'video' AND mime_type LIKE 'video/%'))), CONSTRAINT CHK_DOG_MEDIA_SIZE CHECK (size_bytes > 0), CONSTRAINT CHK_DOG_MEDIA_DIMENSIONS CHECK (((width IS NULL AND height IS NULL) OR (width > 0 AND height > 0)) AND (media_type <> 'image' OR (width IS NOT NULL AND height IS NOT NULL))));
CREATE TABLE treatment_media (id INT GENERATED BY DEFAULT AS IDENTITY NOT NULL, treatment_id INT NOT NULL, storage_key VARCHAR(255) NOT NULL, original_name VARCHAR(255) NOT NULL, mime_type VARCHAR(100) NOT NULL, size_bytes BIGINT NOT NULL, width INT NOT NULL, height INT NOT NULL, position SMALLINT NOT NULL, created_at TIMESTAMP(0) WITH TIME ZONE NOT NULL, PRIMARY KEY (id), CONSTRAINT CHK_TREATMENT_MEDIA_TEXT CHECK (btrim(storage_key) <> '' AND btrim(original_name) <> '' AND mime_type LIKE 'image/%'), CONSTRAINT CHK_TREATMENT_MEDIA_SIZE CHECK (size_bytes > 0 AND width > 0 AND height > 0), CONSTRAINT CHK_TREATMENT_MEDIA_POSITION CHECK (position BETWEEN 1 AND 5));
CREATE INDEX IDX_98013C31634DFEB ON treatment (dog_id);
CREATE INDEX IDX_DOG_MEDIA_DOG_CREATED ON dog_media (dog_id, created_at);
CREATE UNIQUE INDEX UNIQ_DOG_MEDIA_STORAGE_KEY ON dog_media (storage_key);
CREATE UNIQUE INDEX UNIQ_DOG_MEDIA_THUMBNAIL ON dog_media (dog_id) WHERE is_thumbnail = TRUE;
CREATE UNIQUE INDEX UNIQ_DOG_MEDIA_PROFILE ON dog_media (dog_id) WHERE is_profile = TRUE;
CREATE INDEX IDX_TREATMENT_MEDIA_TREATMENT_CREATED ON treatment_media (treatment_id, created_at);
CREATE UNIQUE INDEX UNIQ_TREATMENT_MEDIA_STORAGE_KEY ON treatment_media (storage_key);
CREATE UNIQUE INDEX UNIQ_TREATMENT_MEDIA_POSITION ON treatment_media (treatment_id, position);
ALTER TABLE treatment ADD CONSTRAINT FK_98013C31634DFEB FOREIGN KEY (dog_id) REFERENCES dog (id) ON DELETE RESTRICT NOT DEFERRABLE;
ALTER TABLE dog_media ADD CONSTRAINT FK_DOG_MEDIA_DOG FOREIGN KEY (dog_id) REFERENCES dog (id) ON DELETE CASCADE NOT DEFERRABLE;
ALTER TABLE treatment_media ADD CONSTRAINT FK_TREATMENT_MEDIA_TREATMENT FOREIGN KEY (treatment_id) REFERENCES treatment (id) ON DELETE CASCADE NOT DEFERRABLE;
ALTER TABLE treatment_media DROP CONSTRAINT CHK_TREATMENT_MEDIA_POSITION;
ALTER TABLE treatment_media ADD CONSTRAINT CHK_TREATMENT_MEDIA_POSITION CHECK (position = 1);
CREATE TABLE app_user (id INT GENERATED BY DEFAULT AS IDENTITY NOT NULL, name VARCHAR(100) NOT NULL, email VARCHAR(180) NOT NULL, roles JSON NOT NULL, password VARCHAR(255) NOT NULL, created_at TIMESTAMP(0) WITH TIME ZONE NOT NULL, PRIMARY KEY (id));
CREATE UNIQUE INDEX UNIQ_APP_USER_EMAIL ON app_user (email);
CREATE TABLE dog_owner (dog_id INT NOT NULL, user_id INT NOT NULL, PRIMARY KEY (dog_id, user_id));
CREATE INDEX IDX_54C6AF39634DFEB ON dog_owner (dog_id);
CREATE INDEX IDX_54C6AF39A76ED395 ON dog_owner (user_id);
ALTER TABLE dog_owner ADD CONSTRAINT FK_54C6AF39634DFEB FOREIGN KEY (dog_id) REFERENCES dog (id) ON DELETE CASCADE NOT DEFERRABLE;
ALTER TABLE dog_owner ADD CONSTRAINT FK_54C6AF39A76ED395 FOREIGN KEY (user_id) REFERENCES app_user (id) ON DELETE CASCADE NOT DEFERRABLE;
CREATE TABLE reset_password_request (id INT GENERATED BY DEFAULT AS IDENTITY NOT NULL, user_id INT NOT NULL, selector VARCHAR(20) NOT NULL, hashed_token VARCHAR(100) NOT NULL, requested_at TIMESTAMP(0) WITHOUT TIME ZONE NOT NULL, expires_at TIMESTAMP(0) WITHOUT TIME ZONE NOT NULL, PRIMARY KEY (id));
CREATE INDEX IDX_7CE748AA76ED395 ON reset_password_request (user_id);
CREATE UNIQUE INDEX UNIQ_RESET_PASSWORD_SELECTOR ON reset_password_request (selector);
ALTER TABLE reset_password_request ADD CONSTRAINT FK_RESET_PASSWORD_USER FOREIGN KEY (user_id) REFERENCES app_user (id) ON DELETE CASCADE NOT DEFERRABLE;
